def _model_devi_keywords(workflow_options, ele_temp_f=None, ele_temp_a=None, use_ele_temp=0):
    """Return the extra pair_style keywords requested by the settings."""
    workflow_options = workflow_options or {}
    keywords = []
    if workflow_options.get("use_clusters", False):
        keywords.append("atomic")
    if workflow_options.get("use_relative", False):
        keywords.append("relative %s" % workflow_options["epsilon"])  # noqa: UP031
    if workflow_options.get("use_relative_v", False):
        keywords.append("relative_v %s" % workflow_options["epsilon_v"])  # noqa: UP031
    if ele_temp_f is not None:
        keywords.append("fparam ${ELE_TEMP}")
    elif ele_temp_a is not None:
        keywords.append("aparam ${ELE_TEMP}")
    elif use_ele_temp:
        keywords.append("fparam ${ELE_TEMP}")
    return keywords


def revise_lmp_input_model(
    lmp_lines,
    task_model_list,
    trj_freq,
    deepmd_version="1",
    use_ele_temp=0,
    workflow_options=None,
    ele_temp_f=None,
    ele_temp_a=None,
):
    idx = find_only_one_key(lmp_lines, ["pair_style", "deepmd"])
    graph_list = " ".join(task_model_list)
    if Version(deepmd_version) < Version("1"):
        lmp_lines[idx] = "pair_style      deepmd %s %s model_devi.out\n" % (  # noqa: UP031
            graph_list,
            trj_freq,
        )
        return lmp_lines

    keywords = _model_devi_keywords(
        workflow_options,
        ele_temp_f=ele_temp_f,
        ele_temp_a=ele_temp_a,
        use_ele_temp=use_ele_temp,
    )
    if keywords:
        lmp_lines[idx] = (
            "pair_style      deepmd %s out_freq %s out_file model_devi.out %s\n"  # noqa: UP031
            % (graph_list, trj_freq, " ".join(keywords))
        )
    else:
        lmp_lines[idx] = (
            "pair_style      deepmd %s out_freq %s out_file model_devi.out\n"  # noqa: UP031
            % (graph_list, trj_freq)
        )
    return lmp_lines


def build_template_options(settings, use_ele_temp=0):
    template_options = dict(settings.get("template_options") or {})
    template_options.update(
        {
            "deepmd_version": settings.get("deepmd_version", "1"),
            "use_ele_temp": use_ele_temp,
            "workflow_options": settings.get("workflow_options") or {},
            "ele_temp_f": settings.get("ele_temp_f"),
            "ele_temp_a": settings.get("ele_temp_a"),
        }
    )
    return template_options


def render_external_template_input(template_lines, task_model_list, trj_freq, template_options):
    revised_lines = list(template_lines)
    revised_lines = revise_lmp_input_model(
        revised_lines,
        task_model_list,
        trj_freq,
        deepmd_version=template_options.get("deepmd_version", "1"),
        use_ele_temp=template_options.get("use_ele_temp", 0),
        workflow_options=template_options.get("workflow_options"),
        ele_temp_f=template_options.get("ele_temp_f"),
        ele_temp_a=template_options.get("ele_temp_a"),
    )
    workflow_options = template_options.get("workflow_options") or {}
    revised_lines = revise_lmp_input_dump(
        revised_lines,
        trj_freq,
        model_devi_merge_traj=bool(workflow_options.get("model_devi_merge_traj", False)),
    )
    return revised_lines


def revise_lmp_input_dump(lmp_lines, trj_freq, model_devi_merge_traj=False):
    idx = find_only_one_key(lmp_lines, ["dump"])
    words = lmp_lines[idx].split()
    dump_id = words[1] if len(words) > 1 else "dpgen_dump"
    target_path = "all.lammpstrj" if model_devi_merge_traj else "traj/*.lammpstrj"

    replaced = False
    revised_words = []
    for word in words:
        if "lammpstrj" in word:
            revised_words.append(target_path)
            replaced = True
        else:
            revised_words.append(word)
    if not replaced:
        # Standard LAMMPS dump syntax puts the file name right after the
        # output frequency: dump ID group-ID style N file args
        if len(revised_words) > 5:
            revised_words[5] = target_path
        else:
            revised_words = ["dump", dump_id, "all", "custom", str(trj_freq), target_path]
    lmp_lines[idx] = " ".join(revised_words) + "\n"

    kept_lines = [line for line in lmp_lines if "dump_modify" not in line]
    if model_devi_merge_traj:
        dump_idx = find_only_one_key(kept_lines, ["dump"])
        kept_lines.insert(
            dump_idx + 1,
            f'if "${{restart}} > 0" then "dump_modify     {dump_id} append yes"\n',
        )
    return kept_lines

