from dpgen.generator.run import build_template_options, render_external_template_input

def compact(lines, prefix):
    for raw in lines:
        line = " ".join(raw.split())
        if line.startswith(prefix + " ") or line == prefix:
            return line
    raise RuntimeError("missing " + prefix)

def required_pair(settings):
    wo = settings.get("workflow_options", {})
    req = []
    if wo.get("use_clusters", False): req.append("atomic")
    if wo.get("use_relative", False): req.append(f"relative {wo['epsilon']}")
    if wo.get("use_relative_v", False): req.append(f"relative_v {wo['epsilon_v']}")
    if settings.get("ele_temp_f") is not None:
        req.append("fparam ${ELE_TEMP}")
    elif settings.get("ele_temp_a") is not None:
        req.append("aparam ${ELE_TEMP}")
    req.append(f"out_freq {settings['trj_freq']}")
    req.append("out_file model_devi.out")
    return req

def check(settings, template):
    opts = build_template_options(settings)
    lines = render_external_template_input(template.splitlines(keepends=True), settings["graphs"], settings["trj_freq"], opts)
    pair = compact(lines, "pair_style")
    missing = [t for t in required_pair(settings) if t not in pair]
    dump = compact(lines, "dump")
    wo = settings.get("workflow_options", {})
    merge = bool(wo.get("model_devi_merge_traj", False))
    has_merge = "all.lammpstrj" in dump
    has_traj = "traj/*.lammpstrj" in dump
    has_mod = any("dump_modify" in " ".join(r.split()) for r in lines)
    problems = list(missing)
    if merge:
        if not has_merge: problems.append("missing all.lammpstrj")
        if not has_mod: problems.append("missing dump_modify")
    else:
        if not has_traj: problems.append("missing traj/*.lammpstrj")
        if has_mod: problems.append("unexpected dump_modify")
    return problems

base = {
    "ensemble": "nvt", "conf_file": "conf.data", "graphs": ["graph.000.pb", "graph.001.pb"],
    "nsteps": 100, "dt": 0.5, "neidelay": 10, "trj_freq": 10, "mass_map": [28.0855],
    "temp": 300.0, "tau_t": 0.1, "pres": 1.0, "tau_p": 0.5, "deepmd_version": "1",
    "workflow_options": {},
}
