    for relv in (False, True):
      for merge in (False, True):
        for ele in (None, "f", "a"):
          s = copy.deepcopy(base)
          wo = dict(s["workflow_options"])
          wo["use_clusters"] = clusters
          wo["use_relative"] = rel
          wo["epsilon"] = 1.5
          wo["use_relative_v"] = relv
          wo["epsilon_v"] = 2.0
          wo["model_devi_merge_traj"] = merge
          s["workflow_options"] = wo
          if ele == "f": s["ele_temp_f"] = 1000.0
          if ele == "a": s["ele_temp_a"] = 1000.0
          probs = check(s, template)
          count += 1
          if probs:
              fails += 1
              print("FAIL", clusters, rel, relv, merge, ele, probs)
print("matrix:", count, "fails", fails)
